'use strict';
const cases={
 airbcar:{eyebrow:'CASE STUDY / FULL-STACK PLATFORM / 2025',title:'AIRBCAR',intro:'A car rental platform connecting customers and rental agencies in Morocco.',body:`<div class="case-grid"><section><h3>The problem</h3><p>Connect customers with rental agencies through one application, with a booking flow and distinct access for different user roles.</p><h3>My contribution</h3><p>UI/UX design and frontend development, alongside backend API work using Django and PostgreSQL. The project also involved booking workflows and role-based access control.</p></section><section><h3>The system</h3><p>Django APIs and PostgreSQL support the application’s data and business workflows. Supabase and Redis were integrated for storage and caching. Docker and GitHub Actions support the delivery workflow.</p><h3>What this project demonstrates</h3><p>Connecting interface design, application logic, persistent data, and deployment into one coherent product.</p></section></div><div class="tags"><span>Django</span><span>PostgreSQL</span><span>Supabase</span><span>Redis</span><span>Docker</span><span>GitHub Actions</span></div><p class="case-note">The architecture on this portfolio is an explanatory illustration. Project details are based on the work described in my existing portfolio.</p>`},
 studio:{eyebrow:'CASE STUDY / AUTOMATION & INTEGRATION / 2026',title:'Scripts Studio',intro:'A local production workspace that gives separate scripts a common interface, job history, and a clearer path from input to output.',body:`<img src="/assets/studio-preview.png" alt="Actual Scripts Studio interface"><div class="case-grid"><section><h3>The problem</h3><p>Media scripts had different entry points and inputs. Finding the right tool, understanding its status, and passing results between tools required too many manual steps.</p><h3>The approach</h3><p>A local Python runner and browser dashboard organize the tools around tasks: create a video, discover and download clips, reframe footage, inspect results, and clean generated caches.</p></section><section><h3>Connected workflows</h3><p>Keyword-based clip discovery and downloads feed a reusable library. Downloaded visuals can be selected in the music-video creator. AutoCrop handles social formats and YouTube export dimensions.</p><h3>Operational details</h3><p>Jobs have logs and history, subprocess cancellation, media validation, and explicit cleanup previews with restorable Trash. The dashboard and filesystem operations are covered by automated checks.</p></section></div><div class="tags"><span>Python</span><span>PowerShell</span><span>FFmpeg</span><span>Third-party tool integration</span><span>Local web interface</span></div>`},
 lab:{eyebrow:'PLANNED PROJECT / INFRASTRUCTURE LAB',title:'Learning by building the environment.',intro:'A proposed practice environment for system administration and integration. This lab has not yet been implemented.',body:`<p class="case-note">Planned work, not a completed deployment. The portfolio will be updated with actual diagrams, configuration, and results as the lab develops.</p><div class="case-grid"><section><h3>Start small</h3><p>One Linux virtual machine hosting an application, with repeatable deployment, a health check, and a backup that is tested through restoration.</p><h3>Connect the environment</h3><p>Add a Windows machine, a shared inventory report, and monitoring that helps explain availability and capacity.</p></section><section><h3>Document the evidence</h3><p>Architecture diagrams, configuration scripts, deployment notes, failure scenarios, and the recovery steps that were actually tested.</p><h3>Learning goals</h3><p>Networking, Windows and Linux administration, monitoring, backup and recovery, and reliable system integration.</p></section></div>`}
};

const dialog=document.querySelector('#project-dialog');
let opener;
function openProject(id){const p=cases[id];if(!p)return;opener=document.activeElement;document.querySelector('#case-content').innerHTML=`<p class="eyebrow">${p.eyebrow}</p><h2>${p.title}</h2><p>${p.intro}</p>${p.body}`;if(!dialog.open)dialog.showModal();}
document.querySelectorAll('[data-project]').forEach(b=>b.addEventListener('click',()=>openProject(b.dataset.project)));
document.addEventListener('projectselect',e=>openProject(e.detail));
document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('close',()=>opener?.focus());
dialog.addEventListener('click',e=>{const r=dialog.getBoundingClientRect();if(e.target===dialog&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))dialog.close();});
const views=['home','work','systems','about','contact'];
function navigate(view){if(!views.includes(view))view='home';document.body.dataset.view=view;document.querySelectorAll('.story-panel[data-view]').forEach(p=>p.hidden=p.dataset.view!==view);document.querySelectorAll('.destination-nav button').forEach(b=>{if(b.dataset.go===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});document.querySelector('#sector').textContent=`SECTOR 0${views.indexOf(view)} / ${view==='home'?'ARRIVAL':view.toUpperCase()}`;document.querySelector('main').scrollTop=0;document.dispatchEvent(new CustomEvent('worldnavigate',{detail:view}));}
document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>{if(location.hash==='#'+b.dataset.go)navigate(b.dataset.go);else location.hash=b.dataset.go;}));
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
navigate(location.hash.slice(1));
document.querySelector('#read-mode').addEventListener('click',e=>{const on=document.body.classList.toggle('reading');e.currentTarget.setAttribute('aria-pressed',String(on));e.currentTarget.textContent=on?'Return to 3D':'Reading view';});
